head.script:
//
        (function() {
            const storageKey = 'theme-preference';
            const saved = localStorage.getItem(storageKey);
            const theme = saved ? saved : (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
            document.documentElement.setAttribute('data-theme', theme);

            // Critical CSS for initial theme to prevent flash
            const style = document.createElement('style');
            if (theme === 'dark') {
                style.innerHTML = 'html, body { background-color: #0f172a !important; color: #f8fafc !important; }';
            } else {
                style.innerHTML = 'html, body { background-color: #ffffff !important; color: #0f172a !important; }';
            }
            document.head.appendChild(style);
            window.addEventListener('DOMContentLoaded', () => {
                setTimeout(() => style.remove(), 1000);
            });
        })();
    //

head.b:skin:
/*
<Group description="Global Colors" title="Global Colors">
    <Variable name="primary.color" description="Primary Color" type="color" default="#6366f1"/>
    <Variable name="secondary.color" description="Secondary Color" type="color" default="#a855f7"/>
    <Variable name="accent.color" description="Accent Color" type="color" default="#f43f5e"/>
    <Variable name="bg.color" description="Background Color" type="color" default="#0f172a"/>
    <Variable name="surface.color" description="Surface Color" type="color" default="#1e293b"/>
    <Variable name="text.color" description="Main Text Color" type="color" default="#f8fafc"/>
    <Variable name="muted.text.color" description="Muted Text Color" type="color" default="#94a3b8"/>
</Group>

<Group description="Typography" title="Typography">
    <Variable name="body.font" description="Body Font" type="font" default="font-family: 'Inter', sans-serif;"/>
    <Variable name="heading.font" description="Heading Font" type="font" default="font-family: 'Inter', sans-serif; font-weight: 800;"/>
</Group>

<Group description="Buttons" title="Buttons">
    <Variable name="button.bg" description="Button Background" type="color" default="#6366f1"/>
    <Variable name="button.text" description="Button Text" type="color" default="#ffffff"/>
    <Variable name="button.radius" description="Button Border Radius" type="length" default="50px"/>
</Group>

<Group description="Cards" title="Cards">
    <Variable name="card.bg" description="Card Background" type="color" default="#1e293b"/>
    <Variable name="card.shadow" description="Card Shadow" type="string" default="0 10px 15px -3px rgba(0, 0, 0, 0.1)"/>
    <Variable name="card.radius" description="Card Border Radius" type="length" default="24px"/>
</Group>

<Group description="Forms &amp; Inputs" title="Forms &amp; Inputs">
    <Variable name="input.bg" description="Input Background" type="color" default="#1e293b"/>
    <Variable name="input.border" description="Input Border" type="color" default="#334155"/>
    <Variable name="input.text" description="Input Text" type="color" default="#f8fafc"/>
    <Variable name="input.focus.border" description="Input Focus Border" type="color" default="#6366f1"/>
</Group>
*/

:root {
    --primary: $(primary.color);
    --secondary: $(secondary.color);
    --accent: $(accent.color);
    --bg: $(bg.color);
    --surface: $(surface.color);
    --text: $(text.color);
    --text-muted: $(muted.text.color);

    --btn-bg: $(button.bg);
    --btn-text: $(button.text);
    --btn-radius: $(button.radius);

    --card-bg: $(card.bg);
    --card-shadow: $(card.shadow);
    --card-radius: $(card.radius);

    --input-bg: $(input.bg);
    --input-border: $(input.border);
    --input-text: $(input.text);
    --input-focus: $(input.focus.border);

    --blur: 16px;
    --glass-bg: rgba(255, 255, 255, 0.05);
    --glass-border: rgba(255, 255, 255, 0.1);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Light Mode Overrides */
[data-theme='light'] {
    --bg: #ffffff;
    --surface: #f8fafc;
    --text: #0f172a;
    --text-muted: #64748b;
    --card-bg: #ffffff;
    --card-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
    --input-bg: #f8fafc;
    --input-border: #e2e8f0;
    --input-text: #0f172a;
    --glass-bg: rgba(255, 255, 255, 0.7);
    --glass-border: rgba(0, 0, 0, 0.05);
}

/* Global Styles */
body {
    background-color: var(--bg);
    color: var(--text);
    font-family: 'Inter', sans-serif;
    margin: 0;
    padding: 0;
    line-height: 1.6;
    transition: background-color 0.3s, color 0.3s;
}

/* Layout Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1.5rem;
    width: 100%;
    box-sizing: border-box;
}

/* Responsive Grids */
.grid {
    display: grid;
    gap: 2rem;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

@media (max-width: 768px) {
    .grid {
        grid-template-columns: 1fr;
    }
}

/* Header Styling */
header {
    position: fixed;
    top: 1.5rem;
    left: 50%;
    transform: translateX(-50%);
    width: 90%;
    max-width: 1200px;
    z-index: 1000;
    background: var(--glass-bg);
    backdrop-filter: blur(var(--blur));
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
header.scrolled {
    top: 0;
    width: 100%;
    max-width: 100%;
    border-radius: 0;
    border-top: none;
    border-left: none;
    border-right: none;
    padding: 0.2rem 0;
}
.nav-wrapper {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 80px;
}
.logo {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--primary);
    text-decoration: none;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* Hero Section */
.hero {
    padding: 10rem 0 5rem;
    text-align: center;
}
.hero h1 {
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    line-height: 1.1;
    margin-bottom: 1.5rem;
    background: linear-gradient(135deg, var(--text), var(--primary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.hero p {
    font-size: 1.25rem;
    color: var(--text-muted);
    max-width: 600px;
    margin: 0 auto 2.5rem;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    padding: 1rem 2.5rem;
    background: var(--btn-bg);
    color: var(--btn-text);
    border-radius: var(--btn-radius);
    font-weight: 600;
    text-decoration: none;
    transition: var(--transition);
    border: none;
    cursor: pointer;
}
.btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px -10px var(--primary);
    filter: brightness(1.1);
}
.btn-outline {
    background: transparent;
    border: 1px solid var(--input-border);
    color: var(--text);
}

/* Cards */
.card {
    background: var(--card-bg);
    border-radius: var(--card-radius);
    padding: 2.5rem;
    border: 1px solid var(--glass-border);
    box-shadow: var(--card-shadow);
    transition: var(--transition);
}
.card:hover {
    transform: translateY(-10px);
    border-color: var(--primary);
}

/* Contact Form Advanced Styling */
.contact-form-widget {
    max-width: 600px;
    margin: 0 auto;
    padding: 2rem;
    background: var(--card-bg);
    border-radius: var(--card-radius);
    border: 1px solid var(--glass-border);
}
.contact-form-name, .contact-form-email, .contact-form-email-message {
    width: 100%;
    max-width: 100% !important;
    background: var(--input-bg) !important;
    border: 1px solid var(--input-border) !important;
    color: var(--input-text) !important;
    border-radius: 12px !important;
    padding: 1rem !important;
    margin-bottom: 1.5rem !important;
    transition: var(--transition) !important;
    box-sizing: border-box;
}
.contact-form-name:focus, .contact-form-email:focus, .contact-form-email-message:focus {
    border-color: var(--input-focus) !important;
    box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.1) !important;
    outline: none !important;
}
.contact-form-button-submit {
    background: var(--btn-bg) !important;
    color: var(--btn-text) !important;
    border-radius: var(--btn-radius) !important;
    padding: 1rem 3rem !important;
    width: 100% !important;
    border: none !important;
    font-weight: 600 !important;
    cursor: pointer !important;
    transition: var(--transition) !important;
}
.contact-form-button-submit:hover {
    filter: brightness(1.1) !important;
    transform: translateY(-2px) !important;
}

/* Sections */
section {
    padding: 8rem 0;
}
.section-title {
    text-align: center;
    margin-bottom: 4rem;
}
.section-title h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

/* Footer */
footer {
    padding: 5rem 0;
    border-top: 1px solid var(--glass-border);
    text-align: center;
    color: var(--text-muted);
}

/* Scroll Top */
#scrollTop {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    width: 50px;
    height: 50px;
    background: var(--primary);
    color: white;
    border: none;
    border-radius: 50%;
    display: none;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 100;
    box-shadow: 0 10px 20px -5px var(--primary);
}

body.script:
//
        // Theme Management
        const themeToggle = document.getElementById('theme-toggle');
        const storageKey = 'theme-preference';

        const getColorPreference = () => {
            if (localStorage.getItem(storageKey))
                return localStorage.getItem(storageKey);
            return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
        };

        let currentTheme = getColorPreference();

        const reflectPreference = () => {
            document.documentElement.setAttribute('data-theme', currentTheme);
            localStorage.setItem(storageKey, currentTheme);
        };

        reflectPreference();

        themeToggle.addEventListener('click', () => {
            currentTheme = currentTheme === 'light' ? 'dark' : 'light';
            reflectPreference();
        });

        // Sticky Header & Scroll Top
        const header = document.getElementById('header');
        const scrollTop = document.getElementById('scrollTop');

        window.addEventListener('scroll', () => {
            if (window.scrollY > 50) {
                header.classList.add('scrolled');
                scrollTop.style.display = 'flex';
            } else {
                header.classList.remove('scrolled');
                scrollTop.style.display = 'none';
            }
        });

        scrollTop.addEventListener('click', () => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });

        // Smooth Scroll
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const targetId = this.getAttribute('href');
                if (targetId === '#') return;
                document.querySelector(targetId).scrollIntoView({
                    behavior: 'smooth'
                });
            });
        });
    //
